/* C&D V54: Worker completo y recursos de la app, sin claves privadas. */
const source=require('node:zlib').gunzipSync(Buffer.from("",'base64')).toString('utf8');
function boundary(s){let d=0,q=false,e=false;for(let i=s.indexOf('{');i<s.length;i++){const c=s[i];if(q){if(e)e=false;else if(c==='\\')e=true;else if(c==='"')q=false;}else if(c==='"')q=true;else if(c==='{')d++;else if(c==='}'&&--d===0)return i+1;}throw new Error('Paquete inválido');}
module.exports={workerSource:source,assets:JSON.parse(source.slice(source.indexOf('{'),boundary(source)))};
